-- Bestias.lua (9.3): bestias que puede domesticar un cazador, para el botón Mascotas (Mascotas.lua).
-- Familias con sus habilidades y su dieta, y cada bestia con su nivel, su velocidad de ataque y dónde sale.
-- Bestias y sitios: base de datos de Classic 1.12 (cMaNGOS: bestias domesticables; QuestieDB: dónde salen y nombre en español).
-- 9.5: las bestias propias de WoW Forever (Isla Zephras), el zorro nuevo y el búho renombrado Ave rapaz, de forg.gg y
-- foreverchanges.pro. Casi todos los nombres van en inglés: aún no hay base de datos con los de español. Sin comprobar en el juego.
-- Creado por JKRiveroF.
local _, GL = ...
if type(GL) ~= "table" then return end
local L = GL.L

-- Matriz de familias 71091: Endgame Tools y Bind on Forever, consultadas 26-11-2026.
-- Etiquetas ES propias: prevalece el cliente para la localización oficial.
local HAB_BI = {
  mordisco = {"Mordisco", "Bite", "Ataque directo de la mascota.", "Direct pet attack."},
  zarpa = {"Zarpa", "Claw", "Ataque directo de garras.", "Direct claw attack."},
  carrera = {"Carrera", "Dash", "Aumenta temporalmente la velocidad terrestre.", "Temporarily increases ground movement speed."},
  picado = {"Picado", "Dive", "Aumenta temporalmente la velocidad de desplazamiento.", "Temporarily increases movement speed."},
  acechar = {"Acechar", "Prowl", "Sigilo que potencia el primer golpe.", "Stealth that empowers the opening hit."},
