  chillido = {"Chillido desmoralizador", "Demoralizing Screech", "Daña y reduce el poder de ataque de enemigos cercanos.", "Deals damage and reduces nearby enemies’ attack power."},
  aliento = {"Aliento de relámpagos", "Lightning Breath", "Daño de Naturaleza a distancia.", "Ranged Nature damage."},
  veneno = {"Veneno de escórpido", "Scorpid Poison", "Aplica un veneno acumulable.", "Applies a stacking poison."},
  escudo = {"Escudo de caparazón", "Shell Shield", "Reduce temporalmente el daño recibido.", "Temporarily reduces incoming damage."},
  pisoton = {"Pisotón atronador", "Thunderstomp", "Daño de área útil para generar amenaza.", "Area damage useful for threat."},
  danza = {"Danza del embaucador", "Trickster's Dance", "Refuerza esquiva y velocidad de ataque.", "Boosts dodge and attack speed."},
