  pellizco = {"Pellizco", "Pinch", "Inflige daño y ralentiza al enemigo.", "Deals damage and slows the enemy."},
  vapulear = {"Vapulear", "Swipe", "Ataque contra varios enemigos próximos.", "Attack against multiple nearby enemies."},
  sonico = {"Estallido sónico", "Sonic Blast", "Inflige daño y ralentiza los lanzamientos enemigos.", "Deals damage and slows enemy casts."},
  desmembrar = {"Desmembrar", "Dismember", "Daña y reduce la sanación que recibe el objetivo.", "Deals damage and reduces healing received."},
  tendones = {"Desgarro de tendones", "Tendon Rip", "Aplica daño periódico y ralentiza.", "Applies periodic damage and slows."},
  salvaje = {"Desgarro salvaje", "Savage Rend", "Aplica un sangrado al enemigo.", "Applies a bleed to the enemy."},
  telarana = {"Telaraña", "Web", "Inmoviliza y causa daño periódico.", "Roots and deals periodic damage."},
  polvo = {"Nube de polvo", "Dust Cloud", "Reduce la armadura del objetivo.", "Reduces target armor."},
  encogerse = {"Encogerse", "Cower", "Reduce la amenaza de la mascota.", "Reduces pet threat."},
}
local HAB = {}
for k,v in pairs(HAB_BI) do HAB[k] = v[1] .. ": " .. v[3] end
function GL.HabilidadBestia(h, soloNombre)
  local v = HAB_BI[h]
  if not v then return h end
  local i = GL.ingles and 2 or 1
  return soloNombre and v[i] or (v[i] .. ": " .. v[i+2])
end


